CREATE TABLE `captain` (`Captain_ID` DECIMAL(18,2), `Name` VARCHAR(100), `Ship_ID` DECIMAL(18,2), `age` VARCHAR(100), `Class` VARCHAR(100), `Rank` VARCHAR(100));
CREATE TABLE `Ship` (`Ship_ID` DECIMAL(18,2), `Name` VARCHAR(100), `Type` VARCHAR(100), `Built_Year` DECIMAL(18,2), `Class` VARCHAR(100), `Flag` VARCHAR(100));
